const saved = (() => {
  try { return localStorage.getItem('lang') } catch { return null }
})()

i18n.use(initReactI18next).init({
  resources: { vi: { translation: vi }, en: { translation: en }, ko: { translation: ko } },
  lng: saved ?? 'vi',
  fallbackLng: 'vi',
  interpolation: { escapeValue: false },
})

// KPI phòng ban (dữ liệu thật + 2 tab Demo): nạp thêm vào các nhánh ws / nav / kpi của từng ngôn ngữ
for (const lng of ['vi', 'en', 'ko'] as const) {
  i18n.addResourceBundle(lng, 'translation', KPI_BUNDLES[lng], true, false)
  i18n.addResourceBundle(lng, 'translation', CMP_EXTRA_BUNDLES[lng], true, false)
  i18n.addResourceBundle(lng, 'translation', IDC_FILTER_BUNDLES[lng], true, false)   // bộ lọc ngày nhập và nơi nhập của màn CCCD
  i18n.addResourceBundle(lng, 'translation', IDC_ERP_BUNDLES[lng], true, false)   // hộp Đồng bộ ERP của màn CCCD
  i18n.addResourceBundle(lng, 'translation', YEAR_REVIEW_BUNDLES[lng], true, false)   // "Năm của tôi" (tổng kết năm)
  i18n.addResourceBundle(lng, 'translation', SITE_BUNDLES[lng], true, false)   // ô chọn cơ sở ở màn đăng nhập + trang chào Hà Nội
  i18n.addResourceBundle(lng, 'translation', HN_BUNDLES[lng], true, false)   // màn cơ sở Ninh Bình (Hà Nam): menu, trang chủ, hồ sơ, chốt công, vân tay, chuông
  i18n.addResourceBundle(lng, 'translation', HN_REQ_BUNDLES[lng], true, false)   // màn xem đơn của cơ sở Ninh Bình (Hà Nam)
  i18n.addResourceBundle(lng, 'translation', MONTH_REVIEW_BUNDLES[lng], true, false)   // "Tháng của tôi" + tủ huy hiệu
  i18n.addResourceBundle(lng, 'translation', REC_GRID_BUNDLES[lng], true, false)   // bảng Quản lý CV sửa trực tiếp + trạng thái đọc CV
  i18n.addResourceBundle(lng, 'translation', ACCOUNT_RECLAIM_BUNDLES[lng], true, false)   // màn Thu hồi tài khoản người nghỉ việc (ERP chỉ đọc + CMS)
  i18n.addResourceBundle(lng, 'translation', CUSTOMS_RECONCILE_BUNDLES[lng], true, false)   // màn Đối soát tờ khai ECUS ↔ ERP (/customs/reconcile)
  i18n.addResourceBundle(lng, 'translation', UI_EXTRA_BUNDLES[lng], true, true)   // chữ còn sót tiếng Việt ở en/ko: khóa thiếu, chữ viết cứng, giá trị server (srv.*)
}

export function setLanguage(code: string) {
  i18n.changeLanguage(code)
  try { localStorage.setItem('lang', code) } catch { /* bỏ qua */ }
}

export default i18n
